from pathlib import Path
root = Path('.')
repos = sorted([p for p in root.iterdir() if (p/'.git').is_dir()], key=lambda p:p.name.lower())
for p in repos:
    flags = []
    for name in ['.agent-os','.claude','.codex','.specify']:
        if (p/name).exists(): flags.append(name)
    for name in ['CLAUDE.md','GEMINI.md','AGENTS.md','MEMORY.md']:
        if (p/name).exists(): flags.append(name)
    print(f"{p.name}: {', '.join(flags) if flags else '-'}")
